export function assertAdmin(req: Request, res: Response): boolean {
  if (!req.authUser) {
    res.status(401).json({ error: "not_authenticated" });
    return false;
  }
  if (!req.authUser.isAdmin && !req.authUser.isOwner) {
    res.status(403).json({ error: "admin_required" });
    return false;
  }
  return true;
}

